description:
Change under review: add a `mean` helper and use it in the report builder. Added files are shown in full. For changed files, only the changed region is shown; the rest of the file, including the `Report` and `ReportError` types, is unchanged and compiles.

`src/types.ts` (unchanged, shown for context):
```ts
3 export type NonEmptyArray<T> = [T, ...T[]];
```

`src/stats/mean.ts` (added):
```ts
1 import type { NonEmptyArray } from "../types.js";
2
3 export function mean(values: NonEmptyArray<number>): number {
4   const total = values.reduce((sum, value) => sum + value, 0);
5   return total / values.length;
6 }
```

`src/stats/report.ts` (changed, lines 1-21):
```ts
1 import { err, ok, type Result } from "neverthrow";
2 import type { NonEmptyArray } from "../types.js";
3 import { mean } from "./mean.js";
4 import type { Report, ReportError } from "./report-types.js";
...
12 export function buildReport(samples: number[]): Result<Report, ReportError> {
13   if (!isNonEmpty(samples)) {
14     return err({ type: "NoSamples" });
15   }
16   return ok({ count: samples.length, mean: mean(samples) });
17 }
18
19 function isNonEmpty<T>(values: T[]): values is NonEmptyArray<T> {
20   return values.length > 0;
21 }
```

